import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
// Training pass 1: grid = (C, S). Each CTA reduces a slice of the batch for
// one channel (f64 partial sum and sum of squares) and atomically accumulates
// the result into global workspaces. Splitting the per-channel reduction over
// S CTAs instead of a single CTA per channel raises grid-level parallelism /
// occupancy (grid-stride parallelization of the reduction).
.visible .entry batchnorm2d_stats_kernel(
    .param .u64 p_x,
    .param .u64 p_sum,
    .param .u64 p_ssq,
    .param .u32 p_n,
    .param .u32 p_c,
    .param .u32 p_hw
)
{
    .reg .pred %p<16>;
    .reg .u32  %r<48>;
    .reg .u64  %rd<40>;
    .reg .f32  %f<8>;
    .reg .f64  %fd<24>;
    .reg .v4 .f32 %vf<4>;
    .shared .align 8 .f64 s_red[512];
    ld.param.u64 %rd1, [p_x];
    ld.param.u64 %rd2, [p_sum];
    ld.param.u64 %rd3, [p_ssq];
    ld.param.u32 %r1, [p_n];
    ld.param.u32 %r2, [p_c];
    ld.param.u32 %r3, [p_hw];
    mov.u32 %r5, %tid.x;
    mov.u32 %r6, %ctaid.x;
    mov.u32 %r7, %ntid.x;
    mov.u32 %r8, %ctaid.y;
    mov.u32 %r9, %nctaid.y;
    shr.u32 %r13, %r3, 2;          // nvec = hw / 4
    and.b32 %r14, %r3, 3;          // tail = hw % 4
    // batches per split bps = ceil(n / nsplit); this CTA covers [b0, b1)
    add.u32 %r15, %r1, %r9;
    sub.u32 %r15, %r15, 1;
    div.u32 %r15, %r15, %r9;
    mul.lo.u32 %r16, %r8, %r15;    // b0
    add.u32 %r17, %r16, %r15;
    min.u32 %r17, %r17, %r1;       // b1
    mov.f64 %fd10, 0d0000000000000000;
    mov.f64 %fd11, 0d0000000000000000;
    mov.f64 %fd13, 0d0000000000000000;
    mov.f64 %fd14, 0d0000000000000000;
    mov.f64 %fd15, 0d0000000000000000;
    mov.f64 %fd16, 0d0000000000000000;
    mov.f64 %fd17, 0d0000000000000000;
    mov.f64 %fd18, 0d0000000000000000;
    mov.u32 %r10, %r16;
ST_N1:
    setp.lt.u32 %p2, %r10, %r17;
    @!%p2 bra ST_REDUCE;
    mul.lo.u32 %r11, %r10, %r2;
    add.u32 %r11, %r11, %r6;
    mul.lo.u32 %r11, %r11, %r3;
    mul.wide.u32 %rd10, %r11, 4;
    add.u64 %rd11, %rd1, %rd10;
    mov.u32 %r12, %r5;
    shl.b32 %r21, %r7, 2;            // stride = 4 * ntid (unroll by 4 for memory-level parallelism)
ST_J1:
    setp.lt.u32 %p3, %r12, %r13;
    @!%p3 bra ST_J1_TAIL;
    add.u32 %r18, %r12, %r7;
    setp.lt.u32 %p13, %r18, %r13;
    add.u32 %r19, %r18, %r7;
    setp.lt.u32 %p14, %r19, %r13;
    add.u32 %r20, %r19, %r7;
    setp.lt.u32 %p15, %r20, %r13;
    mul.wide.u32 %rd13, %r12, 16;
    add.u64 %rd14, %rd11, %rd13;
    ld.global.nc.v4.f32 %vf0, [%rd14];
    mul.wide.u32 %rd15, %r18, 16;
    add.u64 %rd16, %rd11, %rd15;
    @%p13 ld.global.nc.v4.f32 %vf1, [%rd16];
    mul.wide.u32 %rd17, %r19, 16;
    add.u64 %rd18, %rd11, %rd17;
    @%p14 ld.global.nc.v4.f32 %vf2, [%rd18];
    mul.wide.u32 %rd19, %r20, 16;
    add.u64 %rd20, %rd11, %rd19;
    @%p15 ld.global.nc.v4.f32 %vf3, [%rd20];
    cvt.f64.f32 %fd12, %vf0.x;
    add.f64 %fd10, %fd10, %fd12;
    fma.rn.f64 %fd11, %fd12, %fd12, %fd11;
    cvt.f64.f32 %fd12, %vf0.y;
    add.f64 %fd10, %fd10, %fd12;
    fma.rn.f64 %fd11, %fd12, %fd12, %fd11;
    cvt.f64.f32 %fd12, %vf0.z;
    add.f64 %fd10, %fd10, %fd12;
    fma.rn.f64 %fd11, %fd12, %fd12, %fd11;
    cvt.f64.f32 %fd12, %vf0.w;
    add.f64 %fd10, %fd10, %fd12;
    fma.rn.f64 %fd11, %fd12, %fd12, %fd11;
    @%p13 cvt.f64.f32 %fd12, %vf1.x;
    @%p13 add.f64 %fd13, %fd13, %fd12;
    @%p13 fma.rn.f64 %fd14, %fd12, %fd12, %fd14;
    @%p13 cvt.f64.f32 %fd12, %vf1.y;
    @%p13 add.f64 %fd13, %fd13, %fd12;
    @%p13 fma.rn.f64 %fd14, %fd12, %fd12, %fd14;
    @%p13 cvt.f64.f32 %fd12, %vf1.z;
    @%p13 add.f64 %fd13, %fd13, %fd12;
    @%p13 fma.rn.f64 %fd14, %fd12, %fd12, %fd14;
    @%p13 cvt.f64.f32 %fd12, %vf1.w;
    @%p13 add.f64 %fd13, %fd13, %fd12;
    @%p13 fma.rn.f64 %fd14, %fd12, %fd12, %fd14;
    @%p14 cvt.f64.f32 %fd12, %vf2.x;
    @%p14 add.f64 %fd15, %fd15, %fd12;
    @%p14 fma.rn.f64 %fd16, %fd12, %fd12, %fd16;
    @%p14 cvt.f64.f32 %fd12, %vf2.y;
    @%p14 add.f64 %fd15, %fd15, %fd12;
    @%p14 fma.rn.f64 %fd16, %fd12, %fd12, %fd16;
    @%p14 cvt.f64.f32 %fd12, %vf2.z;
    @%p14 add.f64 %fd15, %fd15, %fd12;
    @%p14 fma.rn.f64 %fd16, %fd12, %fd12, %fd16;
    @%p14 cvt.f64.f32 %fd12, %vf2.w;
    @%p14 add.f64 %fd15, %fd15, %fd12;
    @%p14 fma.rn.f64 %fd16, %fd12, %fd12, %fd16;
    @%p15 cvt.f64.f32 %fd12, %vf3.x;
    @%p15 add.f64 %fd17, %fd17, %fd12;
    @%p15 fma.rn.f64 %fd18, %fd12, %fd12, %fd18;
    @%p15 cvt.f64.f32 %fd12, %vf3.y;
    @%p15 add.f64 %fd17, %fd17, %fd12;
    @%p15 fma.rn.f64 %fd18, %fd12, %fd12, %fd18;
    @%p15 cvt.f64.f32 %fd12, %vf3.z;
    @%p15 add.f64 %fd17, %fd17, %fd12;
    @%p15 fma.rn.f64 %fd18, %fd12, %fd12, %fd18;
    @%p15 cvt.f64.f32 %fd12, %vf3.w;
    @%p15 add.f64 %fd17, %fd17, %fd12;
    @%p15 fma.rn.f64 %fd18, %fd12, %fd12, %fd18;
    add.u32 %r12, %r12, %r21;
    bra ST_J1;
ST_J1_TAIL:
    shl.b32 %r18, %r13, 2;
    add.u32 %r18, %r18, %r5;
    setp.lt.u32 %p12, %r5, %r14;
    @!%p12 bra ST_J1_DONE;
    mul.wide.u32 %rd15, %r18, 4;
    add.u64 %rd16, %rd11, %rd15;
    ld.global.nc.f32 %f1, [%rd16];
    cvt.f64.f32 %fd12, %f1;
    add.f64 %fd10, %fd10, %fd12;
    fma.rn.f64 %fd11, %fd12, %fd12, %fd11;
ST_J1_DONE:
    add.u32 %r10, %r10, 1;
    bra ST_N1;
ST_REDUCE:
    add.f64 %fd10, %fd10, %fd13;     // combine the 4 independent partial sums
    add.f64 %fd10, %fd10, %fd15;
    add.f64 %fd10, %fd10, %fd17;
    add.f64 %fd11, %fd11, %fd14;     // combine the 4 independent partial sums of squares
    add.f64 %fd11, %fd11, %fd16;
    add.f64 %fd11, %fd11, %fd18;
    mov.u64 %rd20, s_red;
    mul.wide.u32 %rd21, %r5, 8;
    add.u64 %rd21, %rd20, %rd21;
    add.u64 %rd22, %rd21, 2048;
    st.shared.f64 [%rd21], %fd10;
    st.shared.f64 [%rd22], %fd11;
    bar.sync 0;
    mov.u32 %r19, 128;
ST_RED_LOOP:
    setp.eq.u32 %p4, %r19, 0;
    @%p4 bra ST_RED_DONE;
    setp.lt.u32 %p5, %r5, %r19;
    @!%p5 bra ST_RED_SKIP;
    add.u32 %r20, %r5, %r19;
    mul.wide.u32 %rd23, %r20, 8;
    add.u64 %rd23, %rd20, %rd23;
    add.u64 %rd24, %rd23, 2048;
    ld.shared.f64 %fd14, [%rd23];
    ld.shared.f64 %fd15, [%rd21];
    add.f64 %fd15, %fd15, %fd14;
    st.shared.f64 [%rd21], %fd15;
    ld.shared.f64 %fd16, [%rd24];
    ld.shared.f64 %fd17, [%rd22];
    add.f64 %fd17, %fd17, %fd16;
    st.shared.f64 [%rd22], %fd17;
ST_RED_SKIP:
    bar.sync 0;
    shr.u32 %r19, %r19, 1;
    bra ST_RED_LOOP;
ST_RED_DONE:
    setp.ne.u32 %p6, %r5, 0;
    @%p6 bra ST_EXIT;
    ld.shared.f64 %fd18, [s_red];
    ld.shared.f64 %fd19, [s_red+2048];
    mul.wide.u32 %rd25, %r6, 8;
    add.u64 %rd26, %rd2, %rd25;
    add.u64 %rd27, %rd3, %rd25;
    red.global.add.f64 [%rd26], %fd18;
    red.global.add.f64 [%rd27], %fd19;
ST_EXIT:
    ret;
}
// Pass 2 (training + eval): grid = (C, S). Training CTAs finalize channel
// statistics from the globally accumulated f64 sums (the separate launch
// provides the cross-CTA ordering, so no grid-wide sync is needed) and then
// normalize their batch slice; eval CTAs normalize with the running stats.
.visible .entry batchnorm2d_kernel(
    .param .u64 p_x,
    .param .u64 p_out,
    .param .u64 p_w,
    .param .u64 p_b,
    .param .u64 p_rm,
    .param .u64 p_rv,
    .param .u64 p_nbt,
    .param .u64 p_sum,
    .param .u64 p_ssq,
    .param .u32 p_n,
    .param .u32 p_c,
    .param .u32 p_hw,
    .param .f64 p_eps,
    .param .f64 p_mom,
    .param .u32 p_training
)
{
    .reg .pred %p<16>;
    .reg .u32  %r<48>;
    .reg .u64  %rd<72>;
    .reg .f32  %f<40>;
    .reg .f64  %fd<64>;
    .reg .v4 .f32 %vf<4>;
    ld.param.u64 %rd1, [p_x];
    ld.param.u64 %rd2, [p_out];
    ld.param.u64 %rd3, [p_w];
    ld.param.u64 %rd4, [p_b];
    ld.param.u64 %rd5, [p_rm];
    ld.param.u64 %rd6, [p_rv];
    ld.param.u64 %rd7, [p_nbt];
    ld.param.u64 %rd8, [p_sum];
    ld.param.u64 %rd9, [p_ssq];
    ld.param.u32 %r1, [p_n];
    ld.param.u32 %r2, [p_c];
    ld.param.u32 %r3, [p_hw];
    ld.param.f64 %fd1, [p_eps];
    ld.param.f64 %fd2, [p_mom];
    ld.param.u32 %r4, [p_training];
    mov.u32 %r5, %tid.x;
    mov.u32 %r6, %ctaid.x;
    mov.u32 %r7, %ntid.x;
    mov.u32 %r8, %ctaid.y;
    mov.u32 %r9, %nctaid.y;
    mov.f64 %fd0, 0d0000000000000000;
    mov.f64 %fd3, 0d3FF0000000000000;
    shr.u32 %r13, %r3, 2;          // nvec = hw / 4
    and.b32 %r14, %r3, 3;          // tail = hw % 4
    // batches per split bps = ceil(n / nsplit); this CTA covers [b0, b1)
    add.u32 %r15, %r1, %r9;
    sub.u32 %r15, %r15, 1;
    div.u32 %r15, %r15, %r9;
    mul.lo.u32 %r16, %r8, %r15;    // b0
    add.u32 %r17, %r16, %r15;
    min.u32 %r17, %r17, %r1;       // b1
    setp.eq.u32 %p1, %r4, 0;
    @%p1 bra EVAL_PATH;
    // ---- TRAINING: finalize channel stats from the accumulated sums
    mul.wide.u32 %rd10, %r6, 8;
    add.u64 %rd11, %rd8, %rd10;
    add.u64 %rd12, %rd9, %rd10;
    ld.global.f64 %fd10, [%rd11];  // sum
    ld.global.f64 %fd11, [%rd12];  // sum of squares
    mul.lo.u32 %r24, %r1, %r3;
    cvt.rn.f64.u32 %fd22, %r24;
    div.rn.f64 %fd23, %fd10, %fd22;      // mean
    div.rn.f64 %fd24, %fd11, %fd22;      // E[x^2]
    mul.f64 %fd25, %fd23, %fd23;
    sub.f64 %fd26, %fd24, %fd25;         // biased variance
    max.f64 %fd26, %fd26, %fd0;
    add.f64 %fd28, %fd26, %fd1;
    sqrt.rn.f64 %fd29, %fd28;
    div.rn.f64 %fd31, %fd3, %fd29;       // invstd
    // ---- one thread per channel updates running stats / batch counter
    setp.ne.u32 %p6, %r5, 0;
    @%p6 bra TR_STATS_DONE;
    setp.ne.u32 %p7, %r8, 0;
    @%p7 bra TR_STATS_DONE;
    mul.wide.u32 %rd20, %r6, 4;
    add.u64 %rd21, %rd5, %rd20;          // &running_mean[c]
    add.u64 %rd22, %rd6, %rd20;          // &running_var[c]
    ld.global.f32 %f2, [%rd21];
    ld.global.f32 %f3, [%rd22];
    cvt.f64.f32 %fd32, %f2;
    cvt.f64.f32 %fd33, %f3;
    sub.f64 %fd35, %fd3, %fd2;           // 1 - momentum
    mul.f64 %fd36, %fd35, %fd32;
    fma.rn.f64 %fd37, %fd2, %fd23, %fd36;
    cvt.rn.f32.f64 %f4, %fd37;
    st.global.f32 [%rd21], %f4;
    sub.f64 %fd38, %fd22, %fd3;          // m - 1
    div.rn.f64 %fd39, %fd22, %fd38;      // m / (m - 1)
    mul.f64 %fd40, %fd26, %fd39;         // unbiased variance
    mul.f64 %fd41, %fd35, %fd33;
    fma.rn.f64 %fd42, %fd2, %fd40, %fd41;
    cvt.rn.f32.f64 %f5, %fd42;
    st.global.f32 [%rd22], %f5;
    setp.ne.u32 %p8, %r6, 0;
    @%p8 bra TR_STATS_DONE;
    ld.global.u64 %rd23, [%rd7];
    add.u64 %rd23, %rd23, 1;
    st.global.u64 [%rd7], %rd23;
TR_STATS_DONE:
    // ---- TRAINING: normalize this CTA's batch slice (128-bit vectors)
    mul.wide.u32 %rd24, %r6, 4;
    add.u64 %rd25, %rd3, %rd24;
    add.u64 %rd26, %rd4, %rd24;
    ld.global.f32 %f6, [%rd25];          // weight[c]
    ld.global.f32 %f7, [%rd26];          // bias[c]
    cvt.rn.f32.f64 %f8, %fd23;           // mean
    cvt.rn.f32.f64 %f9, %fd31;           // invstd
    mul.f32 %f14, %f9, %f6;              // alpha = invstd * weight
    mul.f32 %f15, %f8, %f14;             // mean * alpha
    sub.f32 %f15, %f7, %f15;             // beta = bias - mean * alpha
    mov.u32 %r30, %r16;
TR_N2:
    setp.lt.u32 %p9, %r30, %r17;
    @!%p9 bra EXIT;
    mul.lo.u32 %r31, %r30, %r2;
    add.u32 %r31, %r31, %r6;
    mul.lo.u32 %r31, %r31, %r3;
    mul.wide.u32 %rd30, %r31, 4;
    add.u64 %rd31, %rd1, %rd30;
    add.u64 %rd32, %rd2, %rd30;
    mov.u32 %r32, %r5;
    shl.b32 %r33, %r7, 2;            // stride = 4 * ntid (unroll by 4 for memory-level parallelism)
TR_J2:
    setp.lt.u32 %p10, %r32, %r13;
    @!%p10 bra TR_J2_TAIL;
    add.u32 %r34, %r32, %r7;
    setp.lt.u32 %p15, %r34, %r13;
    add.u32 %r35, %r34, %r7;
    setp.lt.u32 %p11, %r35, %r13;
    add.u32 %r36, %r35, %r7;
    setp.lt.u32 %p12, %r36, %r13;
    mul.wide.u32 %rd33, %r32, 16;
    add.u64 %rd34, %rd31, %rd33;
    add.u64 %rd35, %rd32, %rd33;
    ld.global.nc.v4.f32 %vf1, [%rd34];
    mul.wide.u32 %rd36, %r34, 16;
    add.u64 %rd37, %rd31, %rd36;
    add.u64 %rd38, %rd32, %rd36;
    @%p15 ld.global.nc.v4.f32 %vf3, [%rd37];
    mul.wide.u32 %rd39, %r35, 16;
    add.u64 %rd40, %rd31, %rd39;
    add.u64 %rd41, %rd32, %rd39;
    @%p11 ld.global.nc.v4.f32 %vf0, [%rd40];
    mul.wide.u32 %rd42, %r36, 16;
    add.u64 %rd43, %rd31, %rd42;
    add.u64 %rd44, %rd32, %rd42;
    @%p12 ld.global.nc.v4.f32 %vf2, [%rd43];
    fma.rn.f32 %vf1.x, %vf1.x, %f14, %f15;
    fma.rn.f32 %vf1.y, %vf1.y, %f14, %f15;
    fma.rn.f32 %vf1.z, %vf1.z, %f14, %f15;
    fma.rn.f32 %vf1.w, %vf1.w, %f14, %f15;
    st.global.cs.v4.f32 [%rd35], %vf1;
    fma.rn.f32 %vf3.x, %vf3.x, %f14, %f15;
    fma.rn.f32 %vf3.y, %vf3.y, %f14, %f15;
    fma.rn.f32 %vf3.z, %vf3.z, %f14, %f15;
    fma.rn.f32 %vf3.w, %vf3.w, %f14, %f15;
    @%p15 st.global.cs.v4.f32 [%rd38], %vf3;
    fma.rn.f32 %vf0.x, %vf0.x, %f14, %f15;
    fma.rn.f32 %vf0.y, %vf0.y, %f14, %f15;
    fma.rn.f32 %vf0.z, %vf0.z, %f14, %f15;
    fma.rn.f32 %vf0.w, %vf0.w, %f14, %f15;
    @%p11 st.global.cs.v4.f32 [%rd41], %vf0;
    fma.rn.f32 %vf2.x, %vf2.x, %f14, %f15;
    fma.rn.f32 %vf2.y, %vf2.y, %f14, %f15;
    fma.rn.f32 %vf2.z, %vf2.z, %f14, %f15;
    fma.rn.f32 %vf2.w, %vf2.w, %f14, %f15;
    @%p12 st.global.cs.v4.f32 [%rd44], %vf2;
    add.u32 %r32, %r32, %r33;
    bra TR_J2;
TR_J2_TAIL:
    shl.b32 %r18, %r13, 2;
    add.u32 %r18, %r18, %r5;
    setp.lt.u32 %p13, %r5, %r14;
    @!%p13 bra TR_J2_DONE;
    mul.wide.u32 %rd36, %r18, 4;
    add.u64 %rd37, %rd31, %rd36;
    add.u64 %rd38, %rd32, %rd36;
    ld.global.nc.f32 %f10, [%rd37];
    fma.rn.f32 %f13, %f10, %f14, %f15;
    st.global.cs.f32 [%rd38], %f13;
TR_J2_DONE:
    add.u32 %r30, %r30, 1;
    bra TR_N2;
    // ---- EVAL: normalize with running statistics (128-bit vectors)
EVAL_PATH:
    mul.wide.u32 %rd40, %r6, 4;
    add.u64 %rd41, %rd5, %rd40;
    add.u64 %rd42, %rd6, %rd40;
    add.u64 %rd43, %rd3, %rd40;
    add.u64 %rd44, %rd4, %rd40;
    ld.global.f32 %f20, [%rd41];         // running_mean[c]
    ld.global.f32 %f21, [%rd42];         // running_var[c]
    ld.global.f32 %f22, [%rd43];         // weight[c]
    ld.global.f32 %f23, [%rd44];         // bias[c]
    cvt.f64.f32 %fd50, %f21;
    add.f64 %fd51, %fd50, %fd1;
    sqrt.rn.f64 %fd52, %fd51;
    div.rn.f64 %fd54, %fd3, %fd52;
    cvt.rn.f32.f64 %f24, %fd54;          // invstd
    mul.f32 %f29, %f24, %f22;          // alpha = invstd * weight
    mul.f32 %f30, %f20, %f29;          // mean * alpha
    sub.f32 %f30, %f23, %f30;          // beta = bias - mean * alpha
    mov.u32 %r40, %r16;
EV_N:
    setp.lt.u32 %p11, %r40, %r17;
    @!%p11 bra EXIT;
    mul.lo.u32 %r41, %r40, %r2;
    add.u32 %r41, %r41, %r6;
    mul.lo.u32 %r41, %r41, %r3;
    mul.wide.u32 %rd50, %r41, 4;
    add.u64 %rd51, %rd1, %rd50;
    add.u64 %rd52, %rd2, %rd50;
